# backend/document_processor.py
import firebase_admin
from firebase_admin import credentials, storage, firestore
import mistune  # Markdown parser for validation
from datetime import datetime

# Initialize Firebase Admin SDK
cred = credentials.Certificate("path/to/serviceAccountKey.json")
firebase_admin.initialize_app(
    cred,
    {'storageBucket': 'your-project-id.appspot.com'}
)

db = firestore.client()
bucket = storage.bucket()

class MarkdownValidator:
    def __init__(self):
        self.parser = mistune.Parser()
        self.renderer = mistune.HTMLRenderer()

    def validate_content(self, content: str) -> dict:
        """Validate markdown content and enforce documentation standards"""
        try:
            # Basic markdown validation
            ast = self.parser.parse(content)
            html = self.renderer.render(ast)

            # Enforce documentation standards
            issues = []

            # Rule 1: Must start with H1 heading
            if not content.strip().startswith('# '):
                issues.append("Missing main heading (H1) at start of document")

            # Rule 2: Validate image syntax
            if '!' in content:
                import re
                image_pattern = r'!\[.*?\$$(.*?)$$'
                for line in content.split('\n'):
                    if '!' in line and not re.search(image_pattern, line):
                        issues.append("Invalid image syntax detected - use ![alt](url) format")
                        break

            # Rule 3: Required sections
            required_sections = ['## Introduction', '## Usage', '## Examples']
            for section in required_sections:
                if section not in content:
                    issues.append(f"Missing required section: {section}")

            # Rule 4: Minimum content length
            if len(content.split('\n')) < 10:
                issues.append("Document too short - minimum 10 lines required")

            return {
                'valid': len(issues) == 0,
                'html_preview': html,
                'issues': issues,
                'word_count': len(content.split()),
                'timestamp': datetime.now().isoformat()
            }
        except Exception as e:
            return {
                'valid': False,
                'error': str(e),
                'issues': ['Invalid markdown syntax']
            }

def process_document(doc_id: str, content: str):
    """Validate and store document in Firebase"""
    validator = MarkdownValidator()
    validation_result = validator.validate_content(content)

    if not validation_result['valid']:
        raise ValueError(f"Invalid content: {validation_result['issues']}")

    try:
        # Upload markdown file
        blob = bucket.blob(f"docs/{doc_id}.md")
        blob.upload_from_string(content, content_type='text/markdown')

        # Update Firestore metadata
        db.collection('documents').document(doc_id).set({
            'title': doc_id.replace('-', ' ').title(),
            'last_modified': firestore.SERVER_TIMESTAMP,
            'validation': validation_result,
            'status': 'published',
            'word_count': validation_result['word_count']
        }, merge=True)

        return {'success': True, 'validation': validation_result}

    except Exception as e:
        db.collection('logs').add({
            'error': str(e),
            'timestamp': firestore.SERVER_TIMESTAMP
        })
        return {'success': False, 'error': str(e)}

# Example usage
if __name__ == "__main__":
    doc_id = "getting-started"
    try:
        result = process_document(doc_id, "# Getting Started\n\n## Introduction\n...")
        print("Upload result:", result)
    except ValueError as e:
        print("Validation failed:", e)
