// app/docs/[id]/page.tsx
"use client"; // Required for client-side hooks

import { useState, useEffect } from "react";
import { MarkdownRX } from "markdown-rx";
import { usePathname } from "next/navigation";

export default function DocumentationPage({ 
  params 
}: { 
  params: { id: string } 
}) {
  const [content, setContent] = useState("# Loading...");
  const [isEditing, setIsEditing] = useState(false);
  const [validation, setValidation] = useState<any>(null);
  const [document, setDocument] = useState<any>(null);
  const pathname = usePathname();

  // Load document content and metadata
  useEffect(() => {
    const loadDocument = async () => {
      const res = await fetch(`/api/docs/${params.id}`);
      const data = await res.json();

      if (data.content) {
        setContent(data.content);
        setDocument(data.metadata);
      }
    };
    loadDocument();
  }, [params.id]);

  // Validate markdown content
  const handleValidate = async () => {
    const res = await fetch("/api/validate", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ content }),
    });
    const result = await res.json();
    setValidation(result);
  };

  // Save document changes
  const handleSave = async () => {
    const res = await fetch("/api/docs", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ id: params.id, content }),
    });

    if (res.ok) {
      setIsEditing(false);
      alert("Document saved successfully!");
    }
  };

  return (
    <div className="min-h-screen p-8 bg-gray-50">
      <div className="max-w-4xl mx-auto bg-white rounded-lg shadow-md p-8">
        <div className="flex justify-between items-start mb-6">
          <div>
            <h1 className="text-3xl font-bold text-gray-800 capitalize">
              {params.id.replace("-", " \)}
            </h1>
            {document && (
              <p className="text-sm text-gray-500">
                Last modified: {new Date(document.last_modified).toLocaleDateString()}
              </p>
            )}
          </div>
          <div className="flex gap-2">
            <span className={`px-2 py-1 text-xs rounded-full ${
              document?.validation?.valid ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'
            }`}>
              {document?.validation?.valid ? 'Valid' : 'Invalid'}
            </span>
          </div>
        </div>

        <div className="mb-8">
          {isEditing ? (
            <div className="border border-gray-300 rounded-md overflow-hidden">
              <MarkdownRX
                value={content}
                onChange={setContent}
                className="min-h-[500px] p-4 focus:outline-none focus:ring-2 focus:ring-blue-500"
              />
            </div>
          ) : (
            <div 
              className="prose max-w-none p-4 bg-gray-50 rounded-md"
              dangerouslySetInnerHTML={{ __html: content }}
            />
          )}
        </div>

        <div className="flex gap-4 mb-8">
          {isEditing ? (
            <>
              <button
                onClick={handleValidate}
                className="px-4 py-2 bg-yellow-500 text-white rounded hover:bg-yellow-600 transition-colors"
              >
                Validate
              </button>
              <button
                onClick={handleSave}
                className="px-4 py-2 bg-blue-500 text-white rounded hover:bg-blue-600 transition-colors"
              >
                Save Changes
              </button>
            </>
          ) : (
            <button
              onClick={() => setIsEditing(true)}
              className="px-4 py-2 bg-gray-200 text-gray-700 rounded hover:bg-gray-300 transition-colors"
            >
              Edit Document
            </button>
          )}
        </div>

        {/* Validation Results */}
        {validation && (
          <div className={`mt-4 p-4 rounded-md ${
            validation.issues.length > 0 ? 'bg-red-50 border-l-4 border-red-500' : 'bg-green-50 border-l-4 border-green-500'
          }`}>
            <h3 className={`font-bold ${
              validation.issues.length > 0 ? 'text-red-800' : 'text-green-800'
            }`}>
              {validation.issues.length > 0 ? 'Validation Issues' : 'Validation Successful'}
            </h3>
            {validation.issues.length > 0 ? (
              <ul className="list-disc pl-5 text-red-700">
                {validation.issues.map((issue: string, i: number) => (
                  <li key={i}>{issue}</li>
                ))}
              </ul>
            ) : (
              <p className="text-green-700">
                Document meets all formatting standards.
              </p>
            )}
          </div>
        )}
      </div>
    </div>
  );
}
