## 🧮 Algorithms for Efficient Parsing

### 1. **Schema Validation**
We use a schema dictionary to validate table and column existence:

```python
schema = {
    'users': {
        'columns': {
            'id': 'int',
            'name': 'string',
            'age': 'int'
        }
    },
    'orders': {
        'columns': {
            'user_id': 'int',
            'total': 'float'
        }
    }
}
```

### 2. **Recursive Condition Parsing**
Handles nested conditions and operator precedence:

```python
def parse_operand(operand, schema, available_tables):
    if isinstance(operand, dict) and 'op' in operand:
        return parse_condition(operand, schema, available_tables)
    elif isinstance(operand, str):
        parts = operand.split('.')
        if len(parts) == 2:
            table, col = parts
            if table not in schema:
                raise UnknownTableError(table)
            if col not in schema[table]['columns']:
                raise UnknownColumnError(col, table)
            return operand
        else:
            # Unqualified column: check for ambiguity
            col = parts[0]
            matching = [t for t in available_tables if col in schema.get(t, {}).get('columns', {})]
            if not matching:
                raise UnknownColumnError(col)
            elif len(matching) > 1:
                raise AmbiguousColumnError(col, matching)
            return f"{matching[0]}.{col}"
    else:
        return str(operand)

def parse_condition(condition_ast, schema, available_tables):
    if not isinstance(condition_ast, dict):
        return str(condition_ast)
    if 'op' not in condition_ast:
        raise SQLError("Invalid condition: missing 'op' key")
    op = condition_ast['op']
    if op in ['AND', 'OR']:
        left = parse_condition(condition_ast.get('left'), schema, available_tables)
        right = parse_condition(condition_ast.get('right'), schema, available_tables)
        return f"({left} {op} {right})"
    elif op == '=':
        left = parse_operand(condition_ast.get('left'), schema, available_tables)
        right = parse_operand(condition_ast.get('right'), schema, available_tables)
        return f"{left} = {right}"
    elif op in ['>', '<', '>=', '<=', '!=']:
        left = parse_operand(condition_ast.get('left'), schema, available_tables)
        right = parse_operand(condition_ast.get('right'), schema, available_tables)
        return f"{left} {op} {right}"
    else:
        raise SQLError(f"Unsupported operator: {op}")
```

### 3. **FROM Clause Parsing with Schema Validation**

```python
def parse_from(from_clause, schema):
    if not isinstance(from_clause, list):
        from_clause = [from_clause]
    tables = []
    for clause in from_clause:
        table_name = clause['table']
        if table_name not in schema:
            raise UnknownTableError(table_name)
        tables.append(Scan(table_name=table_name))
    if len(tables) == 1:
        return tables[0]
    else:
        result = tables[0]
        for table in tables[1:]:
            result = CrossProduct(left=result, right=table)
        return result
```

### 4. **Main Query Parser with Error Handling**

```python
def parse_query(sql_ast, schema):
    if sql_ast.get('type') != 'select':
        raise SQLError("Only SELECT statements are supported")
    required_clauses = ['columns', 'from']
    for clause in required_clauses:
        if clause not in sql_ast:
            raise MissingClauseError(clause)

    # Parse FROM clause
    ra = parse_from(sql_ast['from'], schema)

    # Collect tables in FROM clause for column validation
    tables_in_from = []
    def collect_tables(node):
        if isinstance(node, Scan):
            tables_in_from.append(node.table_name)
        elif isinstance(node, CrossProduct):
            collect_tables(node.left)
            collect_tables(node.right)
        elif isinstance(node, Join):
            collect_tables(node.left)
            collect_tables(node.right)
    collect_tables(ra)

    # Parse WHERE clause
    where_condition = sql_ast.get('where')
    if where_condition:
        condition_str = parse_condition(where_condition, schema, tables_in_from)
        ra = Select(condition=condition_str, child=ra)

    # Apply SELECT (projection)
    ra = Project(attributes=sql_ast['columns'], child=ra)

    return ra
```

